/**
 * Mutes `projectId` for the actor alone. Idempotent. Guarded the same way as
 * reading the project: the org must be the actor's, the project must exist
 * there, and the actor needs `project:read`.
 */
export async function muteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await muteRepo.mute(orgId, actor.userId, projectId);
}

/** Lifts the actor's own mute. Same guards as {@link muteProject}, and idempotent. */
export async function unmuteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await muteRepo.unmute(orgId, actor.userId, projectId);
}

/** The actor's own muted projects in `orgId`. */
export async function listMutedProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  assertOrgScope(actor, orgId);
  return muteRepo.listMutedProjectIds(orgId, actor.userId);
}

async function assertCanReadProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
}

/**
 * Applies a project mute on top of the preference-derived channels.
 * Returns `null` when no notification should be created.
 */
function channelsForRecipient(
  kind: NotificationKind,
  channels: readonly NotificationChannel[],
  muted: boolean,
): readonly NotificationChannel[] | null {
  if (!muted) return channels;
  if (!PERSONAL_KINDS_WHEN_MUTED.has(kind)) return null;

  const withoutEmail = channels.filter((channel) => channel !== "email");
  return withoutEmail.length === 0 ? null : withoutEmail;
}

