import type { OrgId, ProjectId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("mute-check", "growth");
});

afterAll(() => {
  cleanup();
});

describe("mute project", () => {
  it("covers mute rules", async () => {
    const orgId = tenant.org.id;
    const projectId = tenant.project.id;
    const admin = tenant.actors.admin;

    await muteProject(admin, orgId, projectId);
    await muteProject(admin, orgId, projectId);
    expect(await listMutedProjectIds(admin, orgId)).toEqual([projectId]);

    await expect(
      muteProject(admin, "org_other" as OrgId, projectId),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      muteProject(admin, orgId, "prj_missing" as ProjectId),
    ).rejects.toBeInstanceOf(NotFoundError);

    const outsider = { ...tenant.actors.viewer, role: "viewer" as const, orgId: "org_other" as OrgId };
    await expect(listMutedProjectIds(outsider, orgId)).rejects.toBeInstanceOf(TenantScopeError);

    await preferenceRepo.upsertPreference({
      orgId,
      userId: admin.userId,
      kind: "issue_assigned",
      inApp: true,
      email: true,
      digestOnly: false,
    });
    await preferenceRepo.upsertPreference({
      orgId,
      userId: admin.userId,
      kind: "comment_created",
      inApp: true,
      email: true,
      digestOnly: false,
    });
    await preferenceRepo.upsertPreference({
      orgId,
      userId: admin.userId,
      kind: "comment_mention",
      inApp: false,
      email: true,
      digestOnly: false,
    });

    const assigned = await notify(orgId, "issue_assigned", [admin.userId], {
      title: "Assigned",
      body: "yours",
      href: "/issues/1",
      actorId: null,
      projectId,
    });
    expect(assigned).toHaveLength(1);
    expect(assigned[0]?.channels).toEqual(["in_app"]);
    expect(assigned[0]?.projectId).toBe(projectId);

    const comment = await notify(orgId, "comment_created", [admin.userId], {
      title: "Comment",
      body: "nope",
      href: "/issues/1",
      actorId: null,
      projectId,
    });
    expect(comment).toHaveLength(0);

    const mention = await notify(orgId, "comment_mention", [admin.userId], {
      title: "Mention",
      body: "email only",
      href: "/issues/1",
      actorId: null,
      projectId,
    });
    expect(mention).toHaveLength(0);

    const joined = await notify(orgId, "member_joined", [admin.userId], {
      title: "Joined",
      body: "ok",
      href: "/settings/members",
      actorId: null,
      projectId: null,
    });
    expect(joined).toHaveLength(1);
    expect(joined[0]?.channels).toEqual(["in_app", "email"]);

    const now = new Date();
    const digest = await buildDigest(
      orgId,
      admin.userId,
      toIsoTimestamp(new Date(now.getTime() - 86_400_000)),
      toIsoTimestamp(new Date(now.getTime() + 1_000)),
    );
    expect(digest).toBeNull();

    await unmuteProject(admin, orgId, projectId);
    await unmuteProject(admin, orgId, projectId);
    expect(await listMutedProjectIds(admin, orgId)).toEqual([]);

    const digestAfter = await buildDigest(
      orgId,
      admin.userId,
      toIsoTimestamp(new Date(now.getTime() - 86_400_000)),
      toIsoTimestamp(new Date(now.getTime() + 1_000)),
    );
    expect(digestAfter?.entries.map((entry) => entry.title)).toEqual(["Assigned"]);

    void PermissionDeniedError;
  });
});
